CREATE TABLE `pelanggan` (
  `id` int NOT NULL AUTO_INCREMENT,
  `nama` varchar(100) DEFAULT 'tanpa, nama',
  `telepon` varchar(20) COMMENT 'nomor (hp)',
  `nik` char(16),
  `diagnosa` text,
  PRIMARY KEY (`id`),
  KEY `idx_nik` (`nik`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
